select member_id || '-' || strftime(month_start, '%Y-%m') as member_month, member_id, month_start, count(*) as valid_order_cnt, sum(paid_cents - refund_cents) as net_cents from (select member_id, date_trunc('month', ordered_at) as month_start, paid_cents, refund_cents from {{ ref('orders') }} where status = 'paid' and paid_cents - refund_cents > 0) t group by member_id, month_start